declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';admin_required();
$current=admin_user();$isSuper=admin_is_super($current);$errors=[];$id=max(0,scalar_int($_GET['edit']??$_POST['id']??0));
if(is_post()){
    verify_csrf();$action=scalar_string($_POST['action']??'save');
    try{
        if($action==='reset_2fa'){$target=max(0,scalar_int($_POST['id']??0));if(!$isSuper&&$target!==(int)$current['id'])throw new RuntimeException('فقط مدیر کل می‌تواند احراز هویت مدیر دیگر را بازنشانی کند.');db()->prepare('UPDATE admins SET two_factor_enabled=0,two_factor_secret_enc=NULL WHERE id=?')->execute([$target]);db()->prepare('DELETE FROM admin_recovery_codes WHERE admin_id=?')->execute([$target]);admin_audit_event('admin_2fa_reset','admin',$target);flash('success','احراز هویت دومرحله‌ای مدیر غیرفعال شد.');redirect(app_url('admin/admin-users.php'));}
        $username=trim(scalar_string($_POST['username']??''));$fullName=trim(scalar_string($_POST['full_name']??''));$password=scalar_string($_POST['password']??'');$active=isset($_POST['is_active'])?1:0;$roleRaw=scalar_int($_POST['role_id']??0);$roleId=$roleRaw>0?$roleRaw:null;
        if(!preg_match('/^[A-Za-z0-9._-]{3,80}$/',$username))throw new RuntimeException('نام کاربری معتبر نیست.');if(text_length($fullName)<2||text_length($fullName)>120)throw new RuntimeException('نام مدیر معتبر نیست.');if($id<1&&!admin_password_is_strong($password))throw new RuntimeException('رمز مدیر باید حداقل ۱۲ کاراکتر و شامل رقم و نویسه غیرعددی باشد.');if($password!==''&&!admin_password_is_strong($password))throw new RuntimeException('رمز جدید شرایط امنیتی لازم را ندارد.');
        if($roleId===null&&!$isSuper)throw new RuntimeException('فقط مدیر کل می‌تواند مدیر کل دیگری تعریف کند.');if($roleId!==null){$check=db()->prepare('SELECT id FROM admin_roles WHERE id=? AND is_active=1');$check->execute([$roleId]);if(!$check->fetchColumn())throw new RuntimeException('نقش انتخاب‌شده معتبر نیست.');}
        if($id===(int)$current['id']&&!$active)throw new RuntimeException('نمی‌توانید حساب فعلی خود را غیرفعال کنید.');
        if($id>0){$old=db()->prepare('SELECT * FROM admins WHERE id=?');$old->execute([$id]);$old=$old->fetch();if(!$old)throw new RuntimeException('مدیر پیدا نشد.');if(!$isSuper&&$old['role_id']===null)throw new RuntimeException('ویرایش مدیر کل فقط توسط مدیر کل انجام می‌شود.');if($old['role_id']===null&&($roleId!==null||!$active)){$count=(int)db()->query('SELECT COUNT(*) FROM admins WHERE role_id IS NULL AND is_active=1')->fetchColumn();if($count<=1)throw new RuntimeException('حداقل یک مدیر کل فعال باید باقی بماند.');}}
        $pdo=db();if($id>0){$sql='UPDATE admins SET username=?,full_name=?,role_id=?,is_active=?'.($password!==''?',password_hash=?,last_password_change_at=NOW()':'').' WHERE id=?';$params=[$username,$fullName,$roleId,$active];if($password!=='')$params[]=password_hash($password,PASSWORD_DEFAULT);$params[]=$id;$pdo->prepare($sql)->execute($params);}else{$pdo->prepare('INSERT INTO admins(role_id,username,full_name,password_hash,is_active,last_password_change_at) VALUES(?,?,?,?,?,NOW())')->execute([$roleId,$username,$fullName,password_hash($password,PASSWORD_DEFAULT),$active]);$id=(int)$pdo->lastInsertId();}
        if($id===(int)$current['id']&&$password!=='')$_SESSION['admin_authenticated_at']=time();admin_audit_event('admin_saved','admin',$id,['role_id'=>$roleId,'active'=>$active]);flash('success','اطلاعات مدیر ذخیره شد.');redirect(app_url('admin/admin-users.php?edit='.$id));
    }catch(Throwable $e){$errors[]=$e instanceof PDOException?'نام کاربری تکراری است.':$e->getMessage();}
}
$edit=null;if($id>0){$stmt=db()->prepare('SELECT * FROM admins WHERE id=?');$stmt->execute([$id]);$edit=$stmt->fetch()?:null;}$roles=db()->query('SELECT * FROM admin_roles WHERE is_active=1 ORDER BY name')->fetchAll();$admins=db()->query('SELECT a.*,r.name role_name FROM admins a LEFT JOIN admin_roles r ON r.id=a.role_id ORDER BY a.id')->fetchAll();$adminPage='admins';$adminTitle='مدیران سیستم';require __DIR__.'/partials/header.php';
